// Generates app / tray icons (PNG + multi-size ICO) with no external dependencies.
//
// If assets/source/icon-art.png exists (full-bleed square artwork — the current one was
// generated by Image Summon itself), it is decoded, cropped, downscaled with an area filter
// and masked into a rounded square. Otherwise a procedural sparkle icon is drawn.
import { deflateSync, inflateSync } from 'node:zlib';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const out = path.join(root, 'assets');
const ART = path.join(out, 'source', 'icon-art.png');
mkdirSync(out, { recursive: true });

// Normalized crop of the artwork used for the tray (tiny sizes need the subject larger).
const TRAY_CROP = { x: 0.13, y: 0.06, size: 0.76 };

// ---------------------------------------------------------------- PNG encode / decode
const crcTable = new Uint32Array(256).map((_, n) => {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  return c >>> 0;
});
const crc32 = (buf) => {
  let c = 0xffffffff;
  for (const b of buf) c = crcTable[(c ^ b) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
};
function chunk(type, data) {
  const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
  const td = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(td));
  return Buffer.concat([len, td, crc]);
}
/** img = { w, h, data: Float32Array RGBA 0..1, straight alpha } */
function encodePng(img) {
  const { w, h, data } = img;
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4);
  ihdr[8] = 8; ihdr[9] = 6;
  const raw = Buffer.alloc((w * 4 + 1) * h);
  for (let y = 0; y < h; y++) {
    const o = y * (w * 4 + 1);
    for (let i = 0; i < w * 4; i++) raw[o + 1 + i] = Math.max(0, Math.min(255, Math.round(data[y * w * 4 + i] * 255)));
  }
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr), chunk('IDAT', deflateSync(raw, { level: 9 })), chunk('IEND', Buffer.alloc(0)),
  ]);
}
function decodePng(buf) {
  let p = 8, w, h, depth, ctype, interlace;
  const idat = [];
  while (p < buf.length) {
    const len = buf.readUInt32BE(p); const type = buf.toString('ascii', p + 4, p + 8);
    const d = buf.subarray(p + 8, p + 8 + len);
    if (type === 'IHDR') { w = d.readUInt32BE(0); h = d.readUInt32BE(4); depth = d[8]; ctype = d[9]; interlace = d[12]; }
    else if (type === 'IDAT') idat.push(d);
    else if (type === 'IEND') break;
    p += 12 + len;
  }
  const ch = { 0: 1, 2: 3, 4: 2, 6: 4 }[ctype];
  if (depth !== 8 || !ch || interlace) throw new Error(`unsupported PNG (depth ${depth}, color type ${ctype}, interlace ${interlace})`);
  const raw = inflateSync(Buffer.concat(idat));
  const stride = w * ch, px = Buffer.alloc(stride * h);
  for (let y = 0; y < h; y++) {
    const f = raw[y * (stride + 1)], src = y * (stride + 1) + 1, dst = y * stride;
    for (let x = 0; x < stride; x++) {
      const a = x >= ch ? px[dst + x - ch] : 0, b = y ? px[dst - stride + x] : 0, c = x >= ch && y ? px[dst - stride + x - ch] : 0;
      let v = raw[src + x];
      if (f === 1) v += a; else if (f === 2) v += b; else if (f === 3) v += (a + b) >> 1;
      else if (f === 4) { const pp = a + b - c, pa = Math.abs(pp - a), pb = Math.abs(pp - b), pc = Math.abs(pp - c); v += pa <= pb && pa <= pc ? a : pb <= pc ? b : c; }
      px[dst + x] = v & 0xff;
    }
  }
  const data = new Float32Array(w * h * 4);
  for (let i = 0; i < w * h; i++) {
    const s = i * ch;
    const [r, g, b, al] = ch === 1 ? [px[s], px[s], px[s], 255] : ch === 2 ? [px[s], px[s], px[s], px[s + 1]] : ch === 3 ? [px[s], px[s + 1], px[s + 2], 255] : [px[s], px[s + 1], px[s + 2], px[s + 3]];
    data.set([r / 255, g / 255, b / 255, al / 255], i * 4);
  }
  return { w, h, data };
}

// ---------------------------------------------------------------- image ops
function crop(img, x0, y0, size) {
  const data = new Float32Array(size * size * 4);
  for (let y = 0; y < size; y++) data.set(img.data.subarray(((y0 + y) * img.w + x0) * 4, ((y0 + y) * img.w + x0 + size) * 4), y * size * 4);
  return { w: size, h: size, data };
}
/** Exact area-average (box) resampling, separable, premultiplied alpha. */
function resize(img, W, H) {
  const pass = (src, sw, sh, dw, horizontal) => {
    const n = horizontal ? sw : sh, m = dw, other = horizontal ? sh : sw;
    const dst = horizontal ? new Float32Array(dw * sh * 4) : new Float32Array(sw * dw * 4);
    const scale = n / m;
    for (let j = 0; j < m; j++) {
      const a = j * scale, b = a + scale;
      for (let k = 0; k < other; k++) {
        let r = 0, g = 0, bl = 0, al = 0;
        for (let i = Math.floor(a); i < Math.min(n, Math.ceil(b)); i++) {
          const wgt = Math.min(b, i + 1) - Math.max(a, i);
          const s = (horizontal ? k * sw + i : i * sw + k) * 4;
          const A = src[s + 3] * wgt;
          r += src[s] * A; g += src[s + 1] * A; bl += src[s + 2] * A; al += A;
        }
        const d = (horizontal ? k * dw + j : j * sw + k) * 4;
        dst[d + 3] = al / scale;
        if (al > 0) { dst[d] = r / al; dst[d + 1] = g / al; dst[d + 2] = bl / al; }
      }
    }
    return dst;
  };
  const h1 = pass(img.data, img.w, img.h, W, true);
  return { w: W, h: H, data: pass(h1, W, img.h, H, false) };
}
/** Anti-aliased rounded-square mask (pad / radius as fractions of size). */
function roundMask(img, pad, radius) {
  const s = img.w, half = s / 2 - pad * s, r = Math.min(radius * s, half);
  for (let y = 0; y < s; y++) for (let x = 0; x < s; x++) {
    // signed distance to a rounded rectangle centred in the canvas
    const qx = Math.abs(x + 0.5 - s / 2) - (half - r), qy = Math.abs(y + 0.5 - s / 2) - (half - r);
    const d = Math.hypot(Math.max(qx, 0), Math.max(qy, 0)) + Math.min(Math.max(qx, qy), 0) - r;
    img.data[(y * s + x) * 4 + 3] *= Math.max(0, Math.min(1, 0.5 - d));
  }
  return img;
}
/** Paint the image into a larger transparent canvas (used to inset artwork inside the mask). */
function inset(img, size, pad) {
  const inner = resize(img, size - 2 * pad, size - 2 * pad);
  const data = new Float32Array(size * size * 4);
  for (let y = 0; y < inner.h; y++) data.set(inner.data.subarray(y * inner.w * 4, (y + 1) * inner.w * 4), ((y + pad) * size + pad) * 4);
  return { w: size, h: size, data };
}
/** Orange "busy" badge with a white ring, bottom-right. */
function busyBadge(img) {
  const s = img.w, R = s * 0.2, cx = s - R * 1.02, cy = s - R * 1.02;
  for (let y = 0; y < s; y++) for (let x = 0; x < s; x++) {
    const d = Math.hypot(x + 0.5 - cx, y + 0.5 - cy);
    const ring = Math.max(0, Math.min(1, R + 0.5 - d)), core = Math.max(0, Math.min(1, R * 0.7 + 0.5 - d));
    const i = (y * s + x) * 4;
    const blend = (c, t) => { for (let k = 0; k < 3; k++) img.data[i + k] = img.data[i + k] * (1 - t) + c[k] * t; img.data[i + 3] = img.data[i + 3] * (1 - t) + t; };
    if (ring) blend([1, 1, 1], ring);
    if (core) blend([1, 0.55, 0.12], core);
  }
  return img;
}
/** Light unsharp mask for tiny sizes. */
function sharpen(img, amount) {
  const { w, h, data } = img, src = data.slice();
  for (let y = 1; y < h - 1; y++) for (let x = 1; x < w - 1; x++) for (let k = 0; k < 3; k++) {
    const i = (y * w + x) * 4 + k;
    const blur = (src[i - 4] + src[i + 4] + src[i - w * 4] + src[i + w * 4]) / 4;
    data[i] = Math.max(0, Math.min(1, src[i] + amount * (src[i] - blur)));
  }
  return img;
}

// ---------------------------------------------------------------- procedural fallback
const mix = (a, b, t) => a + (b - a) * t;
function procedural(size, theme) {
  const ss = 4, data = new Float32Array(size * size * 4);
  const sample = (x, y) => {
    const t = (x + y) / 2;
    let col = [0, 1, 2].map((k) => mix(theme[0][k], theme[1][k], t));
    const star = (sx, sy, R) => Math.pow(Math.abs(x - sx) / R, 0.5) + Math.pow(Math.abs(y - sy) / R, 0.5) <= 1;
    const glow = Math.max(0, 1 - Math.hypot(x - 0.47, y - 0.5) / 0.42) * 0.25;
    col = col.map((c) => Math.min(1, c + glow));
    if (star(0.46, 0.52, 0.34) || star(0.73, 0.27, 0.13) || star(0.26, 0.76, 0.08)) col = [1, 1, 1];
    return col;
  };
  for (let py = 0; py < size; py++) for (let px = 0; px < size; px++) {
    const acc = [0, 0, 0];
    for (let sy = 0; sy < ss; sy++) for (let sx = 0; sx < ss; sx++) {
      const c = sample((px + (sx + 0.5) / ss) / size, (py + (sy + 0.5) / ss) / size);
      acc[0] += c[0]; acc[1] += c[1]; acc[2] += c[2];
    }
    data.set([acc[0] / 16, acc[1] / 16, acc[2] / 16, 1], (py * size + px) * 4);
  }
  return { w: size, h: size, data };
}

// ---------------------------------------------------------------- build
function ico(pngs) {
  const header = Buffer.alloc(6);
  header.writeUInt16LE(1, 2); header.writeUInt16LE(pngs.length, 4);
  const dir = Buffer.alloc(16 * pngs.length);
  let offset = 6 + dir.length;
  pngs.forEach(([size, data], i) => {
    const o = i * 16;
    dir[o] = size >= 256 ? 0 : size; dir[o + 1] = size >= 256 ? 0 : size;
    dir.writeUInt16LE(1, o + 4); dir.writeUInt16LE(32, o + 6);
    dir.writeUInt32LE(data.length, o + 8); dir.writeUInt32LE(offset, o + 12);
    offset += data.length;
  });
  return Buffer.concat([header, dir, ...pngs.map((p) => p[1])]);
}

let full, trayArt;
if (existsSync(ART)) {
  const art = decodePng(readFileSync(ART));
  const side = Math.min(art.w, art.h);
  full = crop(art, Math.floor((art.w - side) / 2), Math.floor((art.h - side) / 2), side);
  const t = TRAY_CROP;
  trayArt = crop(full, Math.round(t.x * side), Math.round(t.y * side), Math.round(t.size * side));
  console.log(`using artwork ${path.relative(root, ART)} (${art.w}×${art.h})`);
} else {
  full = procedural(1024, [[0.42, 0.33, 0.98], [0.13, 0.66, 0.96]]);
  trayArt = full;
  console.log('no artwork found, drawing procedural icon');
}

// App icon: Windows-style rounded square with a small transparent margin.
const appIcon = (size) => {
  const pad = size <= 24 ? 0 : Math.round(size * 0.04);
  const img = inset(full, size, pad);
  roundMask(img, pad / size, size <= 24 ? 0.2 : 0.2);
  return size <= 48 ? sharpen(img, 0.35) : img;
};
const trayIcon = (size, busy) => {
  const img = roundMask(resize(trayArt, size, size), 0, 0.22);
  sharpen(img, 0.4);
  return busy ? busyBadge(img) : img;
};

writeFileSync(path.join(out, 'icon.png'), encodePng(appIcon(512)));
writeFileSync(path.join(out, 'icon.ico'), ico([16, 24, 32, 48, 64, 128, 256].map((s) => [s, encodePng(appIcon(s))])));
writeFileSync(path.join(out, 'tray-idle.png'), encodePng(trayIcon(32, false)));
writeFileSync(path.join(out, 'tray-idle@2x.png'), encodePng(trayIcon(64, false)));
writeFileSync(path.join(out, 'tray-busy.png'), encodePng(trayIcon(32, true)));
writeFileSync(path.join(out, 'tray-busy@2x.png'), encodePng(trayIcon(64, true)));
console.log('icons written to', out);
